import{_ as a,o as t,c as s,ao as i}from"./chunks/framework.BK8xRsUh.js";const g=JSON.parse('{"title":"Gauss–Newton inversion","description":"","frontmatter":{},"headers":[],"relativePath":"inversion/gauss_newton.md","filePath":"inversion/gauss_newton.md","lastUpdated":null}'),n={name:"inversion/gauss_newton.md"};function o(h,e,l,r,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="Gauss–Newton-inversion" tabindex="-1">Gauss–Newton inversion <a class="header-anchor" href="#Gauss–Newton-inversion" aria-label="Permalink to &quot;Gauss–Newton inversion {#Gauss–Newton-inversion}&quot;">​</a></h1><p>The classical approach, and the one to reach for first. It is fast, predictable, and its behaviour is well understood after thirty years of use on gravity and magnetic data.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Invert3D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.xyz&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FwdCtrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">               &quot;InvCtrl.GN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C3.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.prior&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="The-idea" tabindex="-1">The idea <a class="header-anchor" href="#The-idea" aria-label="Permalink to &quot;The idea {#The-idea}&quot;">​</a></h2><p>Gravity data never determine a density model on their own — infinitely many models fit any survey equally well. So instead of asking &quot;which model fits the data&quot;, we ask for the model that fits the data <strong>and</strong> is as simple as possible, and we trade the two off:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>minimise   ½‖Wd(Gm − d)‖²  +  ½β‖R W (m − mref)‖²</span></span></code></pre></div><p>The first term is the data misfit. The second is the regularizer: how far the model has strayed from the prior <code>mref</code>, and how rough it is. <code>β</code> sets the balance. Density bounds are enforced throughout by projection, so the answer always stays geologically plausible.</p><h2 id="The-settings-that-matter" tabindex="-1">The settings that matter <a class="header-anchor" href="#The-settings-that-matter" aria-label="Permalink to &quot;The settings that matter {#The-settings-that-matter}&quot;">​</a></h2><h3 id="Bounds" tabindex="-1">Bounds <a class="header-anchor" href="#Bounds" aria-label="Permalink to &quot;Bounds {#Bounds}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Density bounds (kg/m3) : -400 400</span></span></code></pre></div><p>Do not leave these wide. They are the cheapest and most physical regularization you have — set them from the rock types you actually expect, and the inversion cannot invent densities that do not exist in your area.</p><h3 id="Smallness-and-smoothing" tabindex="-1">Smallness and smoothing <a class="header-anchor" href="#Smallness-and-smoothing" aria-label="Permalink to &quot;Smallness and smoothing {#Smallness-and-smoothing}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Smallness weight   : 0.04</span></span>
<span class="line"><span>Smoothing weight x : 1</span></span>
<span class="line"><span>Smoothing weight y : 1</span></span>
<span class="line"><span>Smoothing weight z : 1</span></span></code></pre></div><p>Smallness keeps the model near the prior; smoothing ties neighbouring cells together. The weights are relative to a core cell, so <code>smallness = 1/L²</code> corresponds roughly to a smoothing length of <code>L</code> core cells.</p><p>Raise smoothing if the model is speckled. Raise <code>z</code> on its own if you are getting vertical streaks, which gravity is prone to.</p><h3 id="Weighting-—-do-not-skip-this" tabindex="-1">Weighting — do not skip this <a class="header-anchor" href="#Weighting-—-do-not-skip-this" aria-label="Permalink to &quot;Weighting — do not skip this {#Weighting-—-do-not-skip-this}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sensitivity weighting    : sensitivity</span></span>
<span class="line"><span>Depth weighting exponent : 2</span></span>
<span class="line"><span>Depth weighting z0 (m)   : auto</span></span></code></pre></div><p>Gravity falls off with distance, so a cell just under a station influences the data far more than a deep one. Left alone, the inversion exploits this and plasters everything into the top layer, because that is the cheapest way to fit the data.</p><ul><li><p><strong><code>sensitivity</code></strong> weighting (Li &amp; Oldenburg 2000) uses the sensitivity matrix itself to compensate. This is the default and usually the right choice.</p></li><li><p><strong><code>depth</code></strong> weighting (Li &amp; Oldenburg 1998) uses an analytic <code>(z + z₀)^(-β/2)</code> instead.</p></li><li><p><strong><code>none</code></strong> is available but expect a surface-hugging model.</p></li></ul><h3 id="Beta-cooling" tabindex="-1">Beta cooling <a class="header-anchor" href="#Beta-cooling" aria-label="Permalink to &quot;Beta cooling {#Beta-cooling}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Initial damping factor lambda : auto</span></span>
<span class="line"><span>Lambda cooling factor         : 2</span></span></code></pre></div><p><code>β</code> starts large (a smooth, heavily regularized model) and is divided by the cooling factor after each accepted iteration, letting structure in gradually until the target misfit is reached. <code>auto</code> picks the starting value from the ratio of the largest eigenvalues of the data and model terms, which is almost always better than guessing.</p><p>If a cooled step overshoots the target misfit, the solver bisects <code>β</code> geometrically to land in <code>[0.9, 1] ×</code> target rather than blowing past it — the discrepancy principle.</p><h2 id="Under-the-hood" tabindex="-1">Under the hood <a class="header-anchor" href="#Under-the-hood" aria-label="Permalink to &quot;Under the hood {#Under-the-hood}&quot;">​</a></h2><p>Each iteration solves for a step with projected, Jacobi-preconditioned conjugate gradients over the cells that are off their bounds, then does a backtracking line search. The dense sensitivity matrix is held once in Float32. <code>Maximum CG iterations</code> and <code>CG tolerance</code> control the inner solve; the defaults are rarely worth changing.</p><h2 id="Strengths-and-limits" tabindex="-1">Strengths and limits <a class="header-anchor" href="#Strengths-and-limits" aria-label="Permalink to &quot;Strengths and limits {#Strengths-and-limits}&quot;">​</a></h2><p><strong>Good at</strong>: blocky, compact targets. Dense, regular surveys. Being predictable — the same settings give the same answer, and the parameters mean something you can reason about.</p><p><strong>Less good at</strong>: smoothly varying structure, which the piecewise-constant cell parameterization represents awkwardly; and sparse, irregular surveys, where it tends to put mass where the stations happen to be. In <code>examples/demo2</code> — a graded basin under a scattered survey — it recovers twice the mass it needs and buries it more than three times too deep, and that holds across a wide sweep of its regularization settings.</p><p>That is the case the <a href="./inr">neural inversion</a> was added for.</p>`,29)])])}const u=a(n,[["render",o]]);export{g as __pageData,u as default};
